ALTER TABLE public.trip_drafts ADD COLUMN customer_quote_history jsonb NOT NULL DEFAULT '[]'::jsonb;
COMMENT ON COLUMN public.trip_drafts.customer_quote_history IS 'Append-only confirmed customer quote versions, written only by authorized server RPC; existing payload is not pricing authority.';
CREATE TABLE public.trip_invoice_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mfn_id text NOT NULL UNIQUE DEFAULT ('MFN-I-'||upper(replace(gen_random_uuid()::text,'-',''))),request_id uuid NOT NULL REFERENCES public.ride_requests(id),provider_workspace_id uuid NOT NULL REFERENCES public.workspaces(id),patient_workspace_id uuid REFERENCES public.workspaces(id),billed_workspace_id uuid REFERENCES public.workspaces(id),quote_id uuid NOT NULL UNIQUE,quote_snapshot jsonb NOT NULL,provider_snapshot jsonb NOT NULL,bill_to_snapshot jsonb NOT NULL,total_cents integer NOT NULL CHECK(total_cents>=0),status text NOT NULL DEFAULT 'ready' CHECK(status IN ('draft','ready','sent','payment_pending','paid','failed','canceled','refunded','partially_refunded')),created_by uuid NOT NULL,person_mfn_id text,workspace_mfn_id text,created_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz,sent_at timestamptz);
GRANT SELECT ON public.trip_invoice_documents TO authenticated; GRANT ALL ON public.trip_invoice_documents TO service_role;
ALTER TABLE public.trip_invoice_documents ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.trip_invoice_access(_invoice uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.trip_invoice_documents i JOIN public.workspaces w ON w.id=i.provider_workspace_id WHERE i.id=_invoice AND (public.can_manage_provider_customer_pricing(w.id) OR (NOT _manage AND ((i.patient_workspace_id IS NOT NULL AND public.patient_request_access(i.request_id)) OR EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces b ON b.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=i.billed_workspace_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND b.status='active' AND NOT b.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL))))) $$;
REVOKE ALL ON FUNCTION public.trip_invoice_access(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.trip_invoice_access(uuid,boolean) TO authenticated,service_role;
CREATE POLICY scoped_invoice_document_read ON public.trip_invoice_documents FOR SELECT TO authenticated USING(public.trip_invoice_access(id,false));
CREATE TABLE public.trip_invoice_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES public.trip_invoice_documents(id),action text NOT NULL,actor_id uuid,person_mfn_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trip_invoice_events TO authenticated; GRANT ALL ON public.trip_invoice_events TO service_role;
ALTER TABLE public.trip_invoice_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoice_event_owner_read ON public.trip_invoice_events FOR SELECT TO authenticated USING(public.trip_invoice_access(invoice_id,true));
ALTER TABLE public.trip_payments ADD COLUMN invoice_document_id uuid REFERENCES public.trip_invoice_documents(id), ADD COLUMN stripe_charge_id text, ADD COLUMN amount_refunded_cents integer NOT NULL DEFAULT 0 CHECK(amount_refunded_cents>=0), ADD COLUMN invoice_idempotency_key text, ADD COLUMN stripe_connected_account_id text, ADD COLUMN stripe_checkout_session_id text;
CREATE UNIQUE INDEX invoice_payment_idempotency ON public.trip_payments(invoice_idempotency_key) WHERE invoice_idempotency_key IS NOT NULL;
CREATE FUNCTION public.trip_invoice_immutable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Invoice history is immutable'; END IF; IF NEW.id IS DISTINCT FROM OLD.id OR NEW.mfn_id IS DISTINCT FROM OLD.mfn_id OR NEW.request_id IS DISTINCT FROM OLD.request_id OR NEW.provider_workspace_id IS DISTINCT FROM OLD.provider_workspace_id OR NEW.patient_workspace_id IS DISTINCT FROM OLD.patient_workspace_id OR NEW.billed_workspace_id IS DISTINCT FROM OLD.billed_workspace_id OR NEW.quote_id IS DISTINCT FROM OLD.quote_id OR NEW.quote_snapshot IS DISTINCT FROM OLD.quote_snapshot OR NEW.provider_snapshot IS DISTINCT FROM OLD.provider_snapshot OR NEW.bill_to_snapshot IS DISTINCT FROM OLD.bill_to_snapshot OR NEW.total_cents IS DISTINCT FROM OLD.total_cents OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.person_mfn_id IS DISTINCT FROM OLD.person_mfn_id OR NEW.workspace_mfn_id IS DISTINCT FROM OLD.workspace_mfn_id OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.due_at IS DISTINCT FROM OLD.due_at THEN RAISE EXCEPTION 'Invoice financial snapshots are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_document_immutable BEFORE UPDATE OR DELETE ON public.trip_invoice_documents FOR EACH ROW EXECUTE FUNCTION public.trip_invoice_immutable_guard();
CREATE FUNCTION public.invoice_event_immutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Invoice events are append-only'; END $$;
CREATE TRIGGER invoice_events_immutable BEFORE UPDATE OR DELETE ON public.trip_invoice_events FOR EACH ROW EXECUTE FUNCTION public.invoice_event_immutable_guard();
CREATE FUNCTION public.persist_provider_draft_quote(_draft uuid,_workspace uuid,_actor uuid,_snapshot jsonb,_expected uuid,_replace boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_drafts; latest jsonb; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_workspace AND m.user_id=_actor AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Not available'; END IF;
 SELECT * INTO d FROM public.trip_drafts WHERE id=_draft AND user_id=_actor AND submitted_trip_id IS NULL FOR UPDATE; IF d.id IS NULL THEN RAISE EXCEPTION 'Not available'; END IF;
 latest:=d.customer_quote_history->-1;
 IF (latest->>'id')::uuid IS DISTINCT FROM _expected OR (latest IS NOT NULL AND _replace IS DISTINCT FROM true) THEN RAISE EXCEPTION 'Quote changed; confirmed replacement required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.provider_customer_pricing_versions v WHERE v.id=(_snapshot->>'rateVersionId')::uuid AND v.workspace_id=_workspace AND v.effective_at<=now()) OR (_snapshot->>'totalCents')::numeric<0 OR (_snapshot->>'totalCents')::numeric>2147483647 OR _snapshot->>'mileageSource'<>'manual_confirmed' THEN RAISE EXCEPTION 'Invalid quote'; END IF;
 UPDATE public.trip_drafts SET customer_quote_history=customer_quote_history||jsonb_build_array(_snapshot),workspace_id=_workspace WHERE id=_draft;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT _workspace,'customer_quote_confirmed',_actor,p.mfn_id,w.mfn_id,jsonb_build_object('quote_id',_snapshot->>'id','draft_id',_draft,'mileage_source','manual_confirmed','prior_quote_id',_expected) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=_actor AND w.id=_workspace;
 RETURN _snapshot; END $$;
REVOKE ALL ON FUNCTION public.persist_provider_draft_quote(uuid,uuid,uuid,jsonb,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.persist_provider_draft_quote(uuid,uuid,uuid,jsonb,uuid,boolean) TO service_role;
CREATE FUNCTION public.draft_quote_history_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.customer_quote_history IS DISTINCT FROM OLD.customer_quote_history AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'Quote history is server managed'; END IF; IF jsonb_array_length(NEW.customer_quote_history)<jsonb_array_length(OLD.customer_quote_history) OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(NEW.customer_quote_history) WITH ORDINALITY a(v,ord) WHERE ord<=jsonb_array_length(OLD.customer_quote_history)) IS DISTINCT FROM OLD.customer_quote_history THEN RAISE EXCEPTION 'Quote history is append-only'; END IF; RETURN NEW; END $$;
CREATE TRIGGER draft_quote_history_immutable BEFORE UPDATE ON public.trip_drafts FOR EACH ROW EXECUTE FUNCTION public.draft_quote_history_guard();
ALTER TABLE public.provider_network_profiles ADD COLUMN trip_dispatch_phone text, ADD COLUMN trip_dispatch_phone_designated boolean NOT NULL DEFAULT false;
ALTER TABLE public.trips ADD COLUMN patient_contact_driver_id uuid REFERENCES public.drivers(id), ADD COLUMN patient_driver_phone text, ADD COLUMN patient_driver_provider_confirmed boolean NOT NULL DEFAULT false, ADD COLUMN patient_driver_confirmed boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.set_patient_trip_contact(_trip uuid,_driver uuid,_phone text,_provider_confirmed boolean,_driver_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;ws uuid; BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE; SELECT workspace_id INTO ws FROM public.drivers WHERE id=t.driver_id; IF t.id IS NULL OR t.driver_id IS DISTINCT FROM _driver OR NOT public.can_manage_provider_customer_pricing(ws) OR length(coalesce(_phone,''))>32 OR (_phone IS NOT NULL AND (_provider_confirmed IS DISTINCT FROM true OR _driver_confirmed IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'Not available'; END IF;
 PERFORM set_config('app.patient_contact_confirmed','true',true);
 UPDATE public.trips SET patient_contact_driver_id=CASE WHEN _phone IS NOT NULL THEN _driver END,patient_driver_phone=nullif(trim(_phone),''),patient_driver_provider_confirmed=_provider_confirmed,patient_driver_confirmed=_driver_confirmed WHERE id=_trip;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT ws,'trip_driver_contact_consent',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('trip_id',_trip,'driver_id',_driver,'share',_phone IS NOT NULL,'driver_confirmed',_driver_confirmed) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=ws; END $$;
REVOKE ALL ON FUNCTION public.set_patient_trip_contact(uuid,uuid,text,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_patient_trip_contact(uuid,uuid,text,boolean,boolean) TO authenticated;
CREATE FUNCTION public.trip_contact_change_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN NEW.patient_contact_driver_id:=NULL; NEW.patient_driver_phone:=NULL;NEW.patient_driver_provider_confirmed:=false;NEW.patient_driver_confirmed:=false; ELSIF (NEW.patient_contact_driver_id IS DISTINCT FROM OLD.patient_contact_driver_id OR NEW.patient_driver_phone IS DISTINCT FROM OLD.patient_driver_phone OR NEW.patient_driver_provider_confirmed IS DISTINCT FROM OLD.patient_driver_provider_confirmed OR NEW.patient_driver_confirmed IS DISTINCT FROM OLD.patient_driver_confirmed) AND current_setting('app.patient_contact_confirmed',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Explicit trip contact confirmation required'; END IF;RETURN NEW; END $$;
CREATE TRIGGER trip_contact_guard BEFORE UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.trip_contact_change_guard();
CREATE FUNCTION public.set_trip_dispatch_contact(_workspace uuid,_phone text,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_provider_customer_pricing(_workspace) OR _confirmed IS DISTINCT FROM true OR length(coalesce(_phone,''))>32 THEN RAISE EXCEPTION 'Not available';END IF;UPDATE public.provider_network_profiles SET trip_dispatch_phone=nullif(trim(_phone),''),trip_dispatch_phone_designated=nullif(trim(_phone),'') IS NOT NULL WHERE workspace_id=_workspace; INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT _workspace,'trip_dispatch_contact_designated',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('designated',nullif(trim(_phone),'') IS NOT NULL) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=_workspace; END $$;
REVOKE ALL ON FUNCTION public.set_trip_dispatch_contact(uuid,text,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.set_trip_dispatch_contact(uuid,text,boolean) TO authenticated;